{"purpose": "获取月度工时与回款趋势", "sql": "WITH h AS (
  SELECT DATE_TRUNC('month', te.work_date)::date AS m, SUM(te.hours) AS hours
  FROM agent.time_entries te WHERE te.work_date BETWEEN DATE '2025-11-01' AND DATE '2026-10-18' GROUP BY 1
), r AS (
  SELECT DATE_TRUNC('month', p.paid_date)::date AS m, SUM(p.amount) AS amt
  FROM agent.payments p WHERE p.paid_date BETWEEN DATE '2025-11-01' AND DATE '2026-10-18' GROUP BY 1
)
SELECT TO_CHAR(COALESCE(h.m, r.m),'YYYY-MM') AS "月份", COALESCE(h.hours,0) AS "总工时", COALESCE(r.amt,0) AS "回款"
FROM h FULL JOIN r ON h.m=r.m ORDER BY 1"}

